SELECT t.user_id, t.order_count, t.total_spend, t.last_visit_at,
       p.pet_name AS top_pet_name, p.pet_type AS top_pet_type, p.breed_name AS top_breed_name
FROM (
    
    ORDER BY total_spend DESC, user_id ASC
    LIMIT #{limit} OFFSET #{offset}
) t
LEFT JOIN (
    
) p ON p.user_id = t.user_id
ORDER BY t.total_spend DESC, t.user_id ASC

SELECT t.user_id, t.order_count, t.total_spend, t.last_visit_at,
       p.pet_name AS top_pet_name, p.pet_type AS top_pet_type, p.breed_name AS top_breed_name
FROM (
    
    ORDER BY total_spend DESC, user_id ASC
    LIMIT #{limit}
) t
LEFT JOIN (
    
) p ON p.user_id = t.user_id
ORDER BY t.total_spend DESC, t.user_id ASC

SELECT DISTINCT s.pet_id, s.pet_name, s.pet_type, s.breed_name
FROM order_pet_snapshot s
JOIN pet_order o ON o.id = s.order_id
WHERE o.merchant_id = #{merchantId} AND o.store_id = #{storeId} AND o.user_id = #{userId}
ORDER BY s.pet_id DESC
LIMIT #{limit}

SELECT store_id, merchant_id, user_id, note, version, updated_at
FROM merchant_customer_note
WHERE store_id = #{storeId} AND user_id = #{userId}

SELECT COUNT(*) AS customer_count,
       SUM(c.order_count >= 2) AS repeat_customer_count
FROM (
    SELECT o.user_id, COUNT(*) AS order_count
    FROM pet_order o
    WHERE o.merchant_id = #{merchantId} AND o.store_id = #{storeId}
      AND o.created_at >= #{from} AND o.created_at < #{to}
    GROUP BY o.user_id
) c

SELECT COUNT(*) FROM (
    SELECT o.user_id
    FROM pet_order o
    WHERE o.merchant_id = #{merchantId} AND o.store_id = #{storeId}
    GROUP BY o.user_id
    HAVING MIN(o.created_at) >= #{from} AND MIN(o.created_at) < #{to}
) first_orders

SELECT COUNT(*) FROM pet_order o
WHERE o.merchant_id = #{merchantId} AND o.store_id = #{storeId}
  AND o.service_id = #{serviceId}
  AND o.created_at >= #{from} AND o.created_at < #{to}

SELECT o.id, o.order_no, o.order_stage, o.refund_order_id,
       o.refund_application_status, o.aftersale_status,
       o.pay_amount, o.refunded_amount,
       o.created_at, o.appointment_start_at, o.verified_at
FROM pet_order o
WHERE o.merchant_id = #{merchantId} AND o.store_id = #{storeId}
  AND o.service_id = #{serviceId}
  AND o.created_at >= #{from} AND o.created_at < #{to}
ORDER BY o.created_at DESC, o.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT MAX(s.service_name)
FROM order_service_snapshot s
JOIN pet_order po ON po.id = s.order_id
WHERE po.merchant_id = #{merchantId} AND po.store_id = #{storeId}
  AND s.service_id = #{serviceId}
  AND s.created_at = (
      SELECT MAX(s2.created_at) FROM order_service_snapshot s2
      JOIN pet_order po2 ON po2.id = s2.order_id
      WHERE s2.service_id = #{serviceId}
        AND po2.merchant_id = #{merchantId} AND po2.store_id = #{storeId})

