SELECT DISTINCT o.user_id
FROM pet_order o
WHERE o.merchant_id = #{merchantId} AND o.store_id = #{storeId}
  AND RIGHT(CAST(o.order_no AS char), CHAR_LENGTH(#{suffix})) = #{suffix}
